# rocpiRules: regulations governing the carriage of goods and passengers (Annex I, 2.2 and 2.3):
# CMR, cabotage and access to the market (Regulation (EC) 1072/2009 as amended by 2020/1055),
# coach services (Regulation (EC) 1073/2009), Driver CPC (Directive (EU) 2022/2561), Romanian
# road transport rules (OG 27/2011, ARR, ISCTR, RO e-Transport).
SEG = "DOC"
CAT = "rocpiRules"
